#!/usr/bin/env bash
# SPDX-License-Identifier: AGPL-3.0-or-later
#
# Writes the rules page of every module that checks business rules:
# docs/reference/modules/<moduleId>/rules.md from
# src/Modules/<Module>/<project>.Domain/Rules/rules.json, one section per group
# and one table row per rule. The pages are committed, and the rules gate of
# .devkit/gates.sh fails when one differs from what this script writes.
#
# Usage:  bash .github/scripts/render-rules.sh [<repository root> [<output root>]]
#
# Both default to the repository root; the pages are written below
# <output root>/docs/reference/modules/. Needs jq.
set -uo pipefail

root="${1:-$(git rev-parse --show-toplevel)}"
out="${2:-${root}}"
failed=0
module_id_pattern='^[a-z0-9]+(-[a-z0-9]+)*$'

# jq on Windows ends its lines with CR; strip it so the pages are LF only.
query() { jq -r "$2" <<< "$1" | tr -d '\r'; }

# One section per group and one row per rule, written by a single jq call;
# the severity names the one of a syntax that weighs the rule otherwise.
sections='.groups[]
  | "\n## \(.name)\n\nTaken from \(.standard) and checked under the rule sets "
    + ([.ruleSets[] | "`" + . + "`"] | join(", ")) + ".\n\n"
    + "| Rule | Business term | Severity | Message |\n|---|---|---|---|",
    (.rules[]
      | "| \(.id) | \(.businessTerm // "—") | "
        + .severity
        + (if .severityInUbl then ", in UBL " + .severityInUbl else "" end)
        + (if .severityInCii then ", in CII " + .severityInCii else "" end)
        + " | \(.message) |")'

# render <file> <path>: prints the page of one rules.json, or fails.
render() {
  local file="$1" path="$2" module_id catalog
  catalog="$(tr -d '\r' < "${path}")"
  module_id="$(query "${catalog}" '.moduleId // empty')"
  if ! [[ "${module_id}" =~ ${module_id_pattern} ]]; then
    echo "::error::${file}: moduleId \"${module_id}\" is missing or not a module id" >&2
    return 1
  fi
  cat <<PAGE
<!-- Generated by .github/scripts/render-rules.sh from ${file}. Do not edit. -->
# Rules of the ${module_id} module

The business rules the \`${module_id}\` module checks an e-invoice against
once it fits the XML schema of its syntax. The rule identifiers are the
official ones; the messages are the module's own. A finding of a rule
carries its identifier, its severity, its message, the business term it
concerns and the JSON path of the place in the semantic model. The versions
of the sources are listed under [standards](standards.md). The page is
generated from
\`${file}\`.
PAGE
  query "${catalog}" "${sections}"
}

shopt -s nullglob
for path in "${root}"/src/Modules/*/*.Domain/Rules/rules.json; do
  file="${path#"${root}"/}"
  if ! page="$(render "${file}" "${path}")"; then
    failed=1
    continue
  fi
  module_id="$(tr -d '\r' < "${path}" | jq -r '.moduleId' | tr -d '\r')"
  target="${out}/docs/reference/modules/${module_id}/rules.md"
  mkdir -p "$(dirname "${target}")"
  printf '%s\n' "${page}" > "${target}"
  echo "${target#"${out}"/}"
done

exit "${failed}"
